req.query:
query routes_SearchView_Query(
  $count: Int!
  $cursor: String
  $query: String!
  $filters: String
  $orderBy: OrderBy
  $page: Int
) {
  viewer {
    ...SearchView_viewer_1MtKB9
    id
  }
}

fragment CmsBanner_viewer on Customer {
  cmsBanners(first: 999) {
    edges {
      node {
        id
        title
        link
        urlPaths
        categoryBig
        categorySmall
      }
    }
  }
}

fragment List_viewer on Customer {
  id
  freeShippingAmount
  ...ProductCard_viewer
}

fragment ProductCard_product on Product {
  id
  alerts
  name
  type
  configurables(first: 99) {
    edges {
      node {
        id
        type
        discountCode
        name
        model
        secondModel
        sku
        regularPrice
        price
        priceMatch
        sellable
        nonStock
      }
    }
  }
  model
  secondModel
  regularPrice
  price
  priceDrop
  sku
  urlSlug
  freeShipping
  priorityShipping {
    getByDate
  }
  globalFreeShipping
  preorderDate
  backInStockDate
  nonStock
  onlineOnly
  pickupOnly
  callForPrice
  inStoreOnly
  sellable
  discountCode
  brand {
    id
    name
  }
  loyaltyPoints {
    accruing
    dollars
  }
  labels(first: 999) {
    edges {
      node {
        id
        imageUrl
        placement
        placementProductListing
        placementProductView
        type
      }
    }
  }
  mainImage {
    id
    thumbnail
  }
  priceGreen
}

fragment ProductCard_viewer on Customer {
  id
  freeShippingAmount
}

fragment SearchView_viewer_1MtKB9 on Customer {
  ...List_viewer
  ...CmsBanner_viewer
  configs
  products(first: $count, orderBy: $orderBy, after: $cursor, query: $query, filters: $filters, page: $page) {
    totalCount
    facets {
      __typename
      __isFacetType: __typename
      ... on Facet {
        key
        name
        position
        buckets {
          key
          docCount
          imageUrl
        }
      }
      ... on FacetStats {
        key
        name
        position
        buckets {
          key
          docCount
          to
          from
        }
        max
        min
      }
    }
    canonicalLink
    redirect
    edges {
      node {
        id
        ...ProductCard_product
        __typename
      }
      cursor
    }
    pageInfo {
      endCursor
      hasNextPage
    }
  }
}
